const labels={
 title:['امنیت مدیریت','Management security','Sicurezza amministrazione'],
 intro:['ورود دومرحله‌ای از تغییر کالاها و موجودی محافظت می‌کند. کدهای بازیابی را در جای امن نگه دارید.','Two-step verification protects catalogue and stock changes. Keep recovery codes somewhere safe.','La verifica in due passaggi protegge catalogo e disponibilità. Conserva i codici di recupero al sicuro.'],
 enroll:['فعال‌سازی ورود دومرحله‌ای','Set up two-step verification','Configura la verifica in due passaggi'],
 password:['رمز فعلی مدیر','Current administrator password','Password attuale amministratore'],
 begin:['دریافت کلید اتصال','Get setup key','Ottieni chiave di configurazione'],
 secretHelp:['در Google Authenticator، Microsoft Authenticator یا برنامه مشابه، افزودن کلید دستی را انتخاب کنید. کلید زیر را وارد کرده و کد شش‌رقمی را بنویسید.','In Google Authenticator, Microsoft Authenticator or a similar app, add an account with a manual setup key. Enter the key below, then provide its six-digit code.','In Google Authenticator, Microsoft Authenticator o un’app simile, aggiungi un account con chiave manuale. Inserisci la chiave qui sotto, poi il codice a sei cifre.'],
 code:['کد برنامه یا کد بازیابی','Authenticator or recovery code','Codice dell’app o di recupero'],
 enable:['تأیید و فعال‌سازی','Confirm and enable','Conferma e attiva'],
 verify:['تأیید ورود','Verify sign-in','Verifica accesso'],
 verifyHelp:['برای ورود به مدیریت، کد برنامه تأیید هویت یا یکی از کدهای بازیابی را وارد کنید. هر کد بازیابی فقط یک بار قابل استفاده است.','Enter an authenticator code or one of your recovery codes to enter management. Each recovery code works once.','Inserisci il codice dell’app o un codice di recupero per accedere alla gestione. Ogni codice di recupero è utilizzabile una sola volta.'],
 recovery:['کدهای بازیابی شما','Your recovery codes','I tuoi codici di recupero'],
 recoveryHelp:['این کدها فقط همین‌بار نمایش داده می‌شوند. آن‌ها را در مدیر رمز یا جای امنی خارج از این مرورگر ذخیره کنید. کلید برنامه و این کدها را برای کسی نفرستید.','These codes are shown only now. Save them in a password manager or a secure place outside this browser. Do not share your authenticator key or these codes.','Questi codici vengono mostrati solo adesso. Salvali in un gestore di password o in un luogo sicuro fuori dal browser. Non condividere chiave e codici.'],
 done:['کدها را ذخیره کردم؛ ورود به مدیریت','I saved the codes; enter management','Ho salvato i codici; entra nella gestione'],
 logout:['خروج','Sign out','Esci'],revoke:['خروج از تمام دستگاه‌ها','Sign out of every device','Esci da tutti i dispositivi'],
 enabled:['ورود دومرحله‌ای فعال است','Two-step verification is enabled','Verifica in due passaggi attiva'],
 sessions:['نشست‌های فعال','Active sessions','Sessioni attive'],events:['رویدادهای امنیتی اخیر','Recent security events','Eventi di sicurezza recenti'],event:['رویداد','Event','Evento'],time:['زمان','Time','Ora'],target:['مسیر','Path','Percorso'],
 mfaCode:['کد معتبر نیست، منقضی شده یا قبلاً استفاده شده است. کد تازه یا کد بازیابی دیگری وارد کنید.','The code is invalid, expired or already used. Try a fresh code or a different recovery code.','Codice non valido, scaduto o già utilizzato. Prova un nuovo codice o un altro codice di recupero.'],
 credentials:['رمز فعلی درست نیست.','The current password is incorrect.','Password attuale errata.'],rateLimit:['تلاش‌های زیادی انجام شده؛ ۱۵ دقیقه دیگر امتحان کنید.','Too many attempts. Try again in 15 minutes.','Troppi tentativi. Riprova tra 15 minuti.'],error:['درخواست انجام نشد. دوباره تلاش کنید.','The request failed. Try again.','Richiesta non riuscita. Riprova.'],
 timeout:['نشست مدیر بعد از ۳۰ دقیقه بی‌کاری یا حداکثر ۸ ساعت پایان می‌یابد.','Administrator sessions expire after 30 idle minutes or eight hours in total.','Le sessioni amministratore scadono dopo 30 minuti di inattività o otto ore totali.']
};
export function createAdminSecurity({main,getLang,api,esc,field,frame,refresh}){
 let secret='',recovery=[],error='',busy=false,currentUser=null,active=false;
 const T=key=>labels[key]?.[({fa:0,en:1,it:2})[getLang()]]||labels.error[0];
 function content(){
  if(recovery.length)return '<h1>'+T('recovery')+'</h1><p>'+T('recoveryHelp')+'</p><ul class="adm-recovery-codes" dir="ltr">'+recovery.map(code=>'<li><code>'+esc(code)+'</code></li>').join('')+'</ul><button type="button" class="adm-button primary" data-security-done>'+T('done')+'</button>';
  const enrolled=currentUser?.mfaEnabled;
  return '<h1>'+T(enrolled?'title':'enroll')+'</h1><p>'+T(enrolled?'verifyHelp':'intro')+'</p>'+(error?'<p class="adm-message adm-error" role="alert">'+esc(T(error in labels?error:'error'))+'</p>':'')+'<form id="admin-security-form" data-security-action="'+(enrolled?'verify':secret?'enable':'enroll')+'">'+(enrolled||secret?(secret?'<p>'+T('secretHelp')+'</p><code class="adm-authenticator-key" dir="ltr">'+esc(secret)+'</code>':'')+field('security-code',T('code'),'','required maxlength="24" autocomplete="one-time-code" dir="ltr"') : field('security-password',T('password'),'','type="password" required maxlength="128" autocomplete="current-password" dir="ltr"'))+'<button type="submit" class="adm-button primary" '+(busy?'disabled':'')+'>'+T(enrolled?'verify':secret?'enable':'begin')+'</button></form><button type="button" class="adm-button secondary" data-security-logout>'+T('logout')+'</button>';
 }
 function gate(user){currentUser=user;main.innerHTML='<section class="adm-security-gate adm-card"><p class="adm-eyebrow">PERSIA MARKET / SECURITY</p>'+content()+'</section>';}
 async function view(user){if(!user?.mfaEnabled){gate(user);return;}active=false;currentUser=user;frame('<div class="adm-heading"><h1>'+T('title')+'</h1></div><section class="adm-card"><p>'+T('enabled')+'</p><p>'+T('timeout')+'</p><div id="security-events" aria-live="polite"></div><button type="button" class="adm-button secondary" data-security-logout-all>'+T('revoke')+'</button></section>');try{const data=await api('/api/account/security');if(!document.querySelector('#security-events'))return;const date=time=>new Intl.DateTimeFormat(getLang()==='fa'?'fa-IR':getLang()==='it'?'it-IT':'en-GB',{dateStyle:'short',timeStyle:'short'}).format(new Date(time));document.querySelector('#security-events').innerHTML='<p>'+T('sessions')+': '+data.sessions.length+'</p><h2>'+T('events')+'</h2><div class="adm-table-wrap"><table class="adm-table"><thead><tr><th>'+T('event')+'</th><th>'+T('time')+'</th><th>'+T('target')+'</th></tr></thead><tbody>'+data.events.map(item=>'<tr><td><code>'+esc(item.event)+'</code></td><td>'+esc(date(item.created))+'</td><td class="adm-security-path">'+esc(item.target)+'</td></tr>').join('')+'</tbody></table></div>';}catch(e){const node=document.querySelector('#security-events');if(node)node.textContent=T('error');}}
 main.addEventListener('submit',async event=>{if(event.target.id!=='admin-security-form')return;event.preventDefault();if(busy)return;busy=true;error='';const form=event.target,action=form.dataset.securityAction;form.querySelector('button').disabled=true;try{const data=await api('/api/auth/mfa/'+action,{method:'POST',body:action==='enroll'?{password:form.querySelector('#security-password').value}:{code:form.querySelector('#security-code').value}});if(action==='enroll'){secret=data.secret;gate(currentUser);}else if(action==='enable'){secret='';recovery=data.recoveryCodes;currentUser=data.user;gate(currentUser);}else{secret='';error='';await refresh();}}catch(e){error=e.code;gate(currentUser);}finally{busy=false;main.querySelector('#admin-security-form button')?.removeAttribute('disabled');}});
 main.addEventListener('click',async event=>{const target=event.target.closest('button');if(!target)return;if(target.hasAttribute('data-security-done')){recovery=[];secret='';active=false;await refresh();}else if(target.hasAttribute('data-security-logout')||target.hasAttribute('data-security-logout-all')){if(target.hasAttribute('data-security-logout-all')&&!confirm(T('revoke')+'?'))return;await api(target.hasAttribute('data-security-logout-all')?'/api/auth/logout-all':'/api/auth/logout',{method:'POST',body:{}});secret='';recovery=[];error='';await refresh();}});
 return {gate,view,hasRecovery:()=>recovery.length>0,label:()=>T('title')};
}
